struct Line { units: Int, price: Int }

fn value(line: Line) -> Int {
    line.units * line.price
}

fn total_value(lines: Vec<Line>) -> Int {
    let mut acc = 0
    for line in lines {
        acc = acc + value(line)
    }
    acc
}

fn main() {
    let line1 = Line { units: 4, price: 3 }
    let line2 = Line { units: 5, price: 2 }
    print(value(line1))
    print(value(line2))
    let lines = push(push(vec(), line1), line2)
    print(total_value(lines))
}

